import json

def decode_preferences(text):
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return {}

def sum_prices(values):
    if not values:
        return []
    return [sum(values)]

def require_currency(currency):
    if currency not in {'INR', 'EUR'}:
        raise ValueError('Unsupported currency')
    return currency
